interface DisclaimerProps {
  asOfDate?: string;
  className?: string;
}

export const DISCLAIMER_TEMPLATE =
  "Educational outlook generated by models and AI from data up to {as_of_date}. It is not investment advice and is not a signal to trade any security.";

export function formatDisclaimer(asOfDate?: string): string {
  const dateStr = asOfDate && asOfDate.trim() ? asOfDate : "the latest close";
  return DISCLAIMER_TEMPLATE.replace("{as_of_date}", dateStr);
}

export function Disclaimer({ asOfDate, className = "" }: DisclaimerProps) {
  const text = formatDisclaimer(asOfDate);

  return (
    <div
      className={`rounded-md border border-border/60 bg-muted/40 p-3 text-xs leading-relaxed text-muted-foreground ${className}`}
      role="note"
      aria-label="Educational Disclaimer"
    >
      <p>{text}</p>
    </div>
  );
}

